class Solution {
    public List<List<Integer>> findPrimePairs(int n){
        boolean[] prime=new boolean[n+1];
        for(int value=2;value<=n;value++)prime[value]=true;
        for(int value=2;value*value<=n;value++)if(prime[value])for(int multiple=value*value;multiple<=n;multiple+=value)prime[multiple]=false;
        List<List<Integer>> answer=new ArrayList<>();
        for(int first=2;first<=n/2;first++)if(prime[first]&&prime[n-first])answer.add(Arrays.asList(first,n-first));
        return answer;
    }
}

code.kotlin:
class Solution {
    fun findPrimePairs(n:Int):List<List<Int>>{
        val prime=BooleanArray(n+1);
        for(value in 2..n)prime[value]=true;
        var value=2;
        while(value*value<=n){
            if(prime[value]){
                var multiple=value*value;
                while(multiple<=n){
                    prime[multiple]=false;
                    multiple+=value
                }
            };
            value++
        };
        val answer=mutableListOf<List<Int>>();
        for(first in 2..n/2)if(prime[first]&&prime[n-first])answer.add(listOf(first,n-first));
        return answer
    }
}

